import assert from 'node:assert/strict';
import test from 'node:test';
import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { inflateSync } from 'node:zlib';
import * as renderer from '../renderer.js';
const golden = JSON.parse(inflateSync(Buffer.from("", 'base64')));

const logoFixture = readFileSync(new URL('./renderer.test.mjs', import.meta.url), 'utf8').match(/inflateSync\(Buffer\.from\('([^']+)'/)[1];
const logoPixels = { width: 449, height: 445, data: new Uint8ClampedArray(inflateSync(Buffer.from(logoFixture, 'base64'))) };
const letteringFixture = {"sourceSha256":"090ade122b2acc62a7f90c191bdd7a497f07113daa68efaa12b44536aeae2ced","rgbaSha256":"d754299c7e41ee95145fd8b9860bd6a79d34e8886c8d1d8aea85c15eb219ed2d","paths":[{"bbox":{"x":39.98099899291992,"y":8.163000106811523,"width":12.06399917602539,"height":11.868999481201172},"dSha":"3078df9147e3dc46ede2a308d4387d2e9bedf211b2e28b468883d9e5f72f9f15"},{"bbox":{"x":52.95500183105469,"y":8.085000038146973,"width":12.284996032714844,"height":11.817000389099121},"dSha":"4cb28f5ae0e4fcc3329046a84b7a886a971c8cfa6e0dadcd616fddbf1be77945"},{"bbox":{"x":65.85099792480469,"y":8.097999572753906,"width":11.51800537109375,"height":11.884958267211914},"dSha":"b8ecb29084d3b7e846988bd5db512f01b2328b8ecbc5b434cad5a82b53311d64"},{"bbox":{"x":79.03299713134766,"y":8.020000457763672,"width":11.921005249023438,"height":11.947000503540039},"dSha":"5887bfcefe02715e9f015f39b4f5749e51144e437b9a05bab66aa70518357740"},{"bbox":{"x":92.5270004272461,"y":7.9679999351501465,"width":11.543998718261719,"height":12.05099868774414},"dSha":"16fdaa4ee7566d941e752ab91dfe97e553e097461c3e212e2a7cc76007acbf3e"}]};
const textPixels = { width: 1290, height: 250, data: new Uint8ClampedArray(inflateSync(Buffer.from("", 'base64'))) };

// Immutable output fixtures come from accepted Vector788c251, not the implementation under test.
for (const [name, cases] of [['particlePoseAt', golden.particles], ['fieldPoseAt', golden.field]]) for (const entry of cases) assert.deepEqual(renderer[name](...entry.args), entry.out, name + ' retains accepted physical trajectories');

function createHarness(width = 390, height = 844, options = {}) {
  let draws = [], fontStage = 0, nextId = 0;
  const callbacks = new Map(), listeners = {};
  globalThis.requestAnimationFrame = callback => { callbacks.set(++nextId, callback); return nextId; };
  globalThis.cancelAnimationFrame = id => callbacks.delete(id);
  globalThis.window = { devicePixelRatio: 1, addEventListener() {}, removeEventListener() {} };
  globalThis.document = {
    hidden: false, addEventListener(name, callback) { listeners[name] = callback; }, removeEventListener() {},
    createElement() { return { getContext() { return { drawImage() {} }; } }; }
  };
  const context = {
    setTransform() {}, drawImage() {}, fillRect() { draws = []; fontStage = 0; },
    set font(value) { this.fontValue = value; fontStage++; }, get font() { return this.fontValue; },
    fillText(char, x, y) { draws.push({ char, x, y, alpha: this.globalAlpha, color: this.fillStyle, fontStage }); }
  };
  const canvas = { getContext: () => context, getBoundingClientRect: () => ({ width, height, left: 0, top: 0 }), parentElement: { addEventListener() {}, removeEventListener() {} } };
  const field = new renderer.AsciiField(canvas, { logoPixels, textPixels, ...options });
  return { field, callbacks, listeners,
    capture(seconds) { if (seconds !== undefined) field.time = seconds; field.render(); return draws; },
    tick(now) { const callback = callbacks.get(field.raf); assert.equal(typeof callback, 'function'); callbacks.delete(field.raf); callback(now); }
  };
}

test('China composition waits for a fixed ten-second opening and completes at its selected total duration', () => {
  const observations = [];
  for (const totalDuration of [30, 45, 60]) {
    const { field } = createHarness(390, 844, { totalDuration });
    const progressAt = seconds => { field.time = seconds; return field.getFrameState?.().formationProgress ?? renderer.timingAt(seconds, field.options).progress; };
    observations.push({ totalDuration, earlyProgress: progressAt(9.999), openingEndProgress: progressAt(10), middleProgress: progressAt(10 + (totalDuration - 10) / 2), finalProgress: progressAt(totalDuration) });
    field.destroy();
  }
  console.log('China fixed-opening total-duration timing: ' + JSON.stringify(observations));
  for (const observation of observations) {
    assert.equal(observation.earlyProgress, 0, 'no logo or institute-name assembly happens during the first ten seconds');
    assert.equal(observation.openingEndProgress, 0);
    assert.equal(observation.middleProgress, .5, 'total duration includes the opening and controls the remaining assembly interval');
    assert.equal(observation.finalProgress, 1, 'the combined composition completes at the selected total deadline');
  }
});

test('actual logo and institute particles visibly wander on the accepted irregular Vector paths before assembly', () => {
  const observations = [];
  for (const [width, height] of [[1440, 900], [390, 844], [320, 568]]) {
    const harness = createHarness(width, height), { field } = harness;
    const capture = seconds => {
      const calls = harness.capture(seconds), title = calls.filter(call => call.fontStage >= 2), background = [], groups = [];
      const extraGlow = title.length === field.title.length * 2 + field.title.filter(point => point.n > .92).length;
      assert.ok(extraGlow || title.length === field.title.length * 2, 'stable identities have two body draws and an optional glow');
      let cursor = 0;
      for (const point of field.title) {
        const group = title.slice(cursor, cursor + 2 + (extraGlow && point.n > .92 ? 1 : 0)); cursor += group.length;
        groups.push({ x: group[0].x, y: group[0].y, alpha: Math.max(group[0].alpha, group[1].alpha) });
      }
      assert.equal(cursor, title.length);
      for (const call of calls.filter(call => call.fontStage === 1)) if (!background.length || call.x !== background.at(-1).x || call.y !== background.at(-1).y) background.push(call);
      return { groups, background, state: field.getFrameState() };
    };
    const frames = [2, 4, 6].map(capture), count = field.title.length;
    let visible = 0, moving = 0, curved = 0, targetDistance = 0, maximumReferenceError = 0;
    for (let id = 0; id < count; id++) {
      const [a, b, c] = frames.map(frame => frame.groups[id]), ab = { x: b.x - a.x, y: b.y - a.y }, bc = { x: c.x - b.x, y: c.y - b.y };
      const lengthA = Math.hypot(ab.x, ab.y), lengthB = Math.hypot(bc.x, bc.y);
      if (a.alpha >= .15) visible++; if (lengthA >= 6) moving++;
      if (lengthA >= 3 && lengthB >= 3 && Math.abs(ab.x * bc.y - ab.y * bc.x) / (lengthA * lengthB) >= .1) curved++;
      targetDistance += Math.hypot(a.x - field.title[id].x, a.y - field.title[id].y);
      for (const frame of frames) {
        const expected = renderer.particlePoseAt(id, field.title[id], { width, height, fontSize: field.title[id].fontSize ?? field.titleFont, flowSeconds: frame.state.flowSeconds, formationProgress: frame.state.formationProgress }, frame.state.sequenceSeconds);
        const actual = frame.groups[id]; maximumReferenceError = Math.max(maximumReferenceError, Math.hypot(actual.x - expected.x, actual.y - expected.y));
        assert.ok(Number.isFinite(actual.x) && Number.isFinite(actual.y) && actual.x >= 0 && actual.x <= width && actual.y >= 0 && actual.y <= height);
      }
    }
    const cols = Math.ceil(width / field.cell); assert.equal(frames[0].background.length, cols * Math.ceil(height / field.row));
    let backgroundMotion = 0;
    for (let id = 0; id < frames[0].background.length; id++) {
      const a = frames[0].background[id], b = frames[1].background[id]; backgroundMotion += Math.hypot(b.x - a.x, b.y - a.y);
      const expected = renderer.fieldPoseAt(id % cols, Math.floor(id / cols), { width, height, cell: field.cell, row: field.row, flowSeconds: frames[0].state.flowSeconds }, frames[0].state.sequenceSeconds);
      maximumReferenceError = Math.max(maximumReferenceError, Math.hypot(a.x - expected.x, a.y - expected.y));
    }
    observations.push({ width, height, visibleFraction: visible / count, movingFraction: moving / count, curvedFraction: curved / count, meanTargetDistance: targetDistance / count, meanBackgroundMotion: backgroundMotion / frames[0].background.length, maximumReferenceError });
    assert.deepEqual(capture(2).groups, frames[0].groups, 'paths are deterministic rather than frame-wise random jitter'); field.destroy();
  }
  console.log('China accepted irregular native motion: ' + JSON.stringify(observations));
  for (const observation of observations) {
    assert.ok(observation.visibleFraction >= .8, 'the opening has visibly bright particles rather than an invisible near-target fade');
    assert.ok(observation.movingFraction >= .5 && observation.curvedFraction >= .5, 'most early particles move visibly along curved paths');
    assert.ok(observation.meanTargetDistance >= Math.min(observation.width, observation.height) * .1, 'particles start scattered away from the final source-derived targets');
    assert.ok(observation.meanBackgroundMotion >= 2, 'background glyph anchors physically wander');
    assert.ok(observation.maximumReferenceError < 1e-9, 'both native layers use the accepted Vector788c251 physical behavior at the integrated phase');
  }
});

test('both transparent source masks produce color-faithful, aspect-correct responsive target compositions', () => {
  const observations = [];
  for (const [width, height] of [[1440, 900], [390, 844], [320, 568]]) {
    const { field } = createHarness(width, height);
    const groups = Object.fromEntries(['logo', 'lettering'].map(part => [part, field.title.filter(point => point.part === part)]));
    observations.push({ width, height, logoSamples: groups.logo.length, letteringSamples: groups.lettering.length });
    assert.ok(groups.logo.length > 150 && groups.lettering.length > 150, 'both the original brand mark and outlined institute name are sampled');
    const layout = renderer.compositionLayoutAt({ width, height }, logoPixels, textPixels);
    for (const [part, mask] of [['logo', logoPixels], ['lettering', textPixels]]) {
      const rect = layout.parts[part];
      assert.ok(rect.x >= 0 && rect.y >= 0 && rect.x + rect.width <= width && rect.y + rect.height <= height, 'both parts fit the viewport');
      assert.ok(Math.abs(rect.width / rect.height - mask.width / mask.height) < 1e-12, 'source masks are scaled uniformly rather than stretched');
      for (const point of groups[part]) {
        assert.equal(point.color, renderer.regionAt(mask, point.sourceX, point.sourceY), 'target color comes from its own exact opaque source region');
        assert.ok(Math.abs(point.x - rect.x - point.sourceX / mask.width * rect.width) < 1e-9);
        assert.ok(Math.abs(point.y - rect.y - point.sourceY / mask.height * rect.height) < 1e-9);
        assert.ok(point.fontSize > 0 && Number.isFinite(point.fontSize));
      }
    }
    const { logo, lettering } = layout.parts;
    if (width > 700) assert.ok(logo.x + logo.width < lettering.x, 'desktop pairs the mark and name horizontally');
    else assert.ok(logo.y + logo.height < lettering.y, 'mobile places the name below the mark');
    assert.ok(groups.logo.some(point => point.color === renderer.BRAND.green));
    assert.ok(groups.lettering.every(point => point.color === renderer.BRAND.blue));
    field.destroy();
  }
  console.log('China combined source-mask geometry: ' + JSON.stringify(observations));
  assert.throws(() => createHarness(390, 844, { textPixels: undefined }), /text|letter|pixel/i, 'the institute-name mask is required rather than silently omitted');
});

test('formed white-background brand glyphs retain bright individual ink and visible transported contrast', () => {
  const observations = [];
  for (const [width, height] of [[1440, 900], [390, 844], [320, 568]]) {
    const harness = createHarness(width, height), { field } = harness;
    function frame(seconds) {
      const calls = harness.capture(seconds).filter(call => call.fontStage === 1), anchors = [], bins = new Map();
      for (const call of calls) {
        if (!anchors.length || call.x !== anchors.at(-1).x || call.y !== anchors.at(-1).y) anchors.push({ x: call.x, y: call.y, alpha: 0 });
        anchors.at(-1).alpha = Math.max(anchors.at(-1).alpha, call.alpha);
        const key = `${Math.floor(call.x / field.cell)},${Math.floor(call.y / field.row)}`;
        bins.set(key, (bins.get(key) ?? 0) + call.alpha);
      }
      const alphas = anchors.map(anchor => anchor.alpha).sort((a, b) => a - b);
      return { anchors, bins, mean: alphas.reduce((sum, alpha) => sum + alpha, 0) / alphas.length, q75: alphas[Math.floor(alphas.length * .75)] };
    }
    const frames = [60, 62, 65].map(frame), [initial, two, five] = frames;
    const inkChange = frame => [...new Set([...initial.bins.keys(), ...frame.bins.keys()])].reduce((sum, key) => sum + Math.abs((initial.bins.get(key) ?? 0) - (frame.bins.get(key) ?? 0)), 0) / initial.anchors.length;
    observations.push({ width, height, minimumMean: Math.min(...frames.map(frame => frame.mean)), minimumQ75: Math.min(...frames.map(frame => frame.q75)), absoluteInk2s: inkChange(two), absoluteInk5s: inkChange(five) });
    field.destroy();
  }
  console.log('China formed individual-glyph brightness and physical ink transport: ' + JSON.stringify(observations));
  for (const observation of observations) {
    assert.ok(observation.minimumMean >= .08, 'individual crossfading glyphs remain visibly bright after formation');
    assert.ok(observation.minimumQ75 >= .095, 'the stronger quarter of background characters remains clearly visible');
    assert.ok(observation.absoluteInk2s >= .03 && observation.absoluteInk5s >= .047, 'moving ink has absolute visible contrast rather than merely a relative change in faint alpha');
  }
});

test('the exact five outlined Chinese glyphs and original five-path logo survive native sampling', () => {
  const sha = bytes => createHash('sha256').update(bytes).digest('hex');
  const logo = readFileSync(new URL('../assets/china-mobile-logo.svg', import.meta.url));
  const text = readFileSync(new URL('../assets/hk-innovation-lettering.svg', import.meta.url));
  assert.equal(sha(logo), 'd2d716e781a4d771e0abc7d3670c5fd5107897a3507128d79b900b5df82f4e93');
  assert.equal(sha(text), letteringFixture.sourceSha256);
  assert.equal(sha(textPixels.data), letteringFixture.rgbaSha256, 'the embedded mask is the repeated native Edge raster of this exact asset');
  const svg = text.toString('utf8'), paths = [...svg.matchAll(/<path\b[^>]*\bd="([^"]+)"/g)];
  assert.equal(paths.length, 5); assert.equal((logo.toString('utf8').match(/<path\b/g) ?? []).length, 5);
  assert.deepEqual(paths.map(path => sha(path[1])), letteringFixture.paths.map(path => path.dSha));
  assert.match(svg, /viewBox="39.8 7.8 64.5 12.5"/); assert.match(svg, /fill="#0085cc"/);
  assert.doesNotMatch(svg, /<(?:text|rect|image|linearGradient|radialGradient)\b|\btransform=|font-family=/i);
  assert.equal(textPixels.data[3], 0, 'the mask background is transparent');
  const observations = [];
  for (const [width, height] of [[1440, 900], [390, 844], [320, 568], [844, 390]]) {
    const harness = createHarness(width, height), { field } = harness;
    const points = field.title.filter(point => point.part === 'lettering');
    const counts = letteringFixture.paths.map(({ bbox }) => points.filter(point => {
      const x = point.sourceX / 20 + 39.8, y = point.sourceY / 20 + 7.8;
      return x >= bbox.x - .01 && x <= bbox.x + bbox.width + .01 && y >= bbox.y - .01 && y <= bbox.y + bbox.height + .01;
    }).length);
    assert.ok(counts.every(count => count >= 35), 'all five outlined glyphs contribute substantial visible source-derived particles');
    const body = harness.capture(60).filter(call => call.fontStage >= 2); let cursor = 0;
    for (const point of field.title) {
      const pair = body.slice(cursor, cursor + 2); cursor += 2 + (point.n > .92 ? 1 : 0);
      assert.equal(pair[0].x, point.x); assert.equal(pair[0].y, point.y); assert.equal(pair[1].x, point.x); assert.equal(pair[1].y, point.y);
      assert.equal(pair[0].color, point.color); assert.equal(pair[1].color, point.color);
      assert.ok(pair[0].alpha + pair[1].alpha >= .8, 'final source particles stay readable');
    }
    assert.equal(cursor, body.length); observations.push({ width, height, glyphSamples: counts }); field.destroy();
  }
  console.log('China exact native five-glyph coverage: ' + JSON.stringify(observations));
});

test('speed and total-duration controls preserve native poses and progress, then change independent rates', () => {
  const observations = [];
  for (const [width, height] of [[1440, 900], [390, 844], [320, 568]]) {
    const harness = createHarness(width, height), { field } = harness;
    let wallNow = 1000; harness.tick(wallNow);
    for (const seconds of [4, 18, 35, 70]) {
      harness.capture(seconds);
      for (const [speed, duration] of [[.25, 30], [2, 60], [1, 45]]) {
        const before = harness.capture(), state = field.getFrameState();
        assert.equal(field.setFlowSpeed(speed), speed); assert.deepEqual(harness.capture(), before, 'speed selection causes no native position, glyph, or opacity jump');
        assert.equal(field.getFrameState().flowSeconds, state.flowSeconds);
        assert.equal(field.setTotalDuration(duration), duration); assert.deepEqual(harness.capture(), before, 'duration selection preserves the current composition and motion phase');
        assert.equal(field.formationProgress, state.formationProgress); assert.equal(field.time, seconds);
        wallNow += 10; harness.tick(wallNow); const next = field.getFrameState();
        assert.ok(Math.abs(next.flowSeconds - state.flowSeconds - .01 * speed * 115.8 / 45) < 1e-12);
        const expected = seconds < 10 ? 0 : Math.min(1, state.formationProgress + .01 / (duration - 10));
        assert.ok(Math.abs(next.formationProgress - expected) < 1e-12);
        field.time = seconds;
      }
    }
    field.setFlowSpeed(2); field.setTotalDuration(30); field.replay();
    assert.equal(field.flowOffset, 0); assert.equal(field.formationOffset, 0); assert.equal(field.time, 0);
    assert.equal(field.flowSpeed, 2); assert.equal(field.totalDuration, 30); assert.equal(field.paused, false);
    const restarted = harness.capture(); field.replaySnapshot = null;
    const fresh = createHarness(width, height, { flowSpeed: 2, totalDuration: 30 });
    assert.deepEqual(fresh.capture(), restarted, 'replay restarts the same deterministic wander while retaining selections'); fresh.field.destroy();
    // Re-establish this harness's globals before its own lifecycle calls.
    field.destroy(); observations.push({ width, height, controls: 'continuous', replay: 'deterministic' });
  }
  console.log('China independent continuous control clocks: ' + JSON.stringify(observations));
});

test('native paint is continuous through opening, glyph crossfades and settlement at every control extreme', () => {
  const observations = [];
  for (const [width, height] of [[1440, 900], [390, 844], [320, 568]]) {
    const harness = createHarness(width, height), { field } = harness;
    function identityPaint(seconds) {
      const calls = harness.capture(seconds), ink = new Map(); let anchor = null, id = -1, titleId = 0;
      for (const call of calls) {
        assert.ok(Number.isFinite(call.alpha) && call.alpha >= 0 && call.alpha <= 1);
        assert.ok(Number.isFinite(call.x) && Number.isFinite(call.y) && call.x >= 0 && call.x <= width && call.y >= 0 && call.y <= height);
        if (call.fontStage === 1) {
          if (!anchor || anchor.x !== call.x || anchor.y !== call.y) id++;
          anchor = call; const key = `background:${id}:${call.char}`; ink.set(key, (ink.get(key) ?? 0) + call.alpha);
        } else ink.set(`title-layer:${titleId++}:${call.char}`, call.alpha);
      }
      return ink;
    }
    const delta = (a, b) => Math.max(...[...new Set([...a.keys(), ...b.keys()])].map(key => Math.abs((a.get(key) ?? 0) - (b.get(key) ?? 0))));
    let boundedMaximum = 0, wallFrameMaximum = 0; const rates = {};
    for (const totalDuration of [30, 45, 60]) for (const flowSpeed of [.25, 1, 2]) {
      field.setTotalDuration(totalDuration); field.setFlowSpeed(flowSpeed); field.time = 0; field.flowOffset = 0; field.formationOffset = 0;
      const checkpoints = [0, .2, .5, .9, 1.1, 4, 9.99, 10, 10.01, totalDuration - .02, totalDuration, totalDuration + .02, 60, 62, 65];
      for (const fraction of [.1, .3, .5, .7, .9]) checkpoints.push(10 + (totalDuration - 10) * fraction);
      // Include each sampled particle's exact staggered-settlement onset.
      for (let id = 0; id < field.title.length; id += Math.max(1, Math.floor(field.title.length / 12))) {
        let low = 0, high = 1;
        for (let k = 0; k < 45; k++) { const mid = (low + high) / 2; if (renderer.particlePoseAt(id, field.title[id], { width, height, formationProgress: mid, flowSeconds: 0 }, 0).settle === 0) low = mid; else high = mid; }
        checkpoints.push(10 + low * (totalDuration - 10) - .01, 10 + high * (totalDuration - 10) + .01);
      }
      const dt = Math.min(1 / 30, 45 / 115.8 / flowSpeed / 30);
      for (const seconds of checkpoints) {
        const a = identityPaint(seconds), canonical = delta(a, identityPaint(seconds + dt));
        const wallDelta = delta(a, identityPaint(seconds + 1 / 30));
        boundedMaximum = Math.max(boundedMaximum, canonical); wallFrameMaximum = Math.max(wallFrameMaximum, wallDelta);
        rates[flowSpeed] = Math.max(rates[flowSpeed] ?? 0, wallDelta);
        assert.ok(canonical < .01, 'unchanged .01 paint continuity applies at a <=1/30 step in both wall and integrated shader phase');
      }
    }
    observations.push({ width, height, boundedMaximum, wallFrameMaximum, wallFrameMaximumBySpeed: rates }); field.destroy();
  }
  console.log('China native opacity control-extreme continuity: ' + JSON.stringify(observations));
});

test('pause and hidden clocks freeze both integrators while reduced motion stays complete through settings and replay', () => {
  const harness = createHarness(390, 844, { flowSpeed: 2, totalDuration: 30 }), { field } = harness;
  harness.tick(1000); harness.tick(1050); const before = field.getFrameState();
  field.setPaused(true); field.tick(9000); assert.deepEqual(field.getFrameState(), before); assert.equal(harness.callbacks.size, 0);
  field.setPaused(false); harness.tick(10000); assert.deepEqual(field.getFrameState(), before);
  harness.tick(10050); assert.ok(Math.abs(field.getFrameState().wallSeconds - before.wallSeconds - .05) < 1e-12);
  const visible = field.getFrameState(); document.hidden = true; harness.listeners.visibilitychange(); field.tick(18000); assert.deepEqual(field.getFrameState(), visible);
  document.hidden = false; harness.listeners.visibilitychange(); harness.tick(20000); assert.deepEqual(field.getFrameState(), visible);
  field.setReduced(true); const still = harness.capture();
  field.setFlowSpeed(.25); field.setTotalDuration(60); assert.deepEqual(harness.capture(), still, 'reduced settings do not animate or alter the exact completed source artwork');
  const time = field.time; field.replay(); field.tick(30000); assert.equal(field.time, time); assert.deepEqual(harness.capture(900), still);
  assert.equal(harness.callbacks.size, 0); field.destroy();
});
